import{_ as o,C as r,o as a,c as n,a2 as d,E as s}from"./chunks/framework.BTLSZHNB.js";const u=JSON.parse('{"title":"Glossary","description":"Common terms used across the Takoform documentation and specification","frontmatter":{"page_title":"Takoform glossary","description":"Common terms used across the Takoform documentation and specification"},"headers":[],"relativePath":"docs/glossary.md","filePath":"docs/glossary.md"}'),i={name:"docs/glossary.md"};function c(m,e,l,p,h,g){const t=r("StatusNote");return a(),n("div",null,[e[0]||(e[0]=d('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Common terms used across the Takoform documentation. Definitions here are summaries; the normative meaning always lives in the <a href="/spec/">specification</a> documents.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Form</strong></td><td>One portable desired-state contract: a named, versioned definition of what a workload needs from any host.</td></tr><tr><td><strong>FormRef</strong></td><td>The exact immutable identity of a Form: API group, <code>kind</code>, definition version, and schema digest. Compatibility is never inferred from a name alone.</td></tr><tr><td><strong>Form Definition</strong></td><td>The deterministic, data-only JSON document describing one Form: desired/observed/output schemas, immutable fields, lifecycle capabilities, and interface descriptors (<a href="/spec/form-definition/">form definition</a>).</td></tr><tr><td><strong>Form Package</strong></td><td>A closed, data-only distribution of one Form Definition plus its fixtures, bound by a canonical content digest (<a href="/spec/form-package/">form package</a>). No executable or credential content is allowed.</td></tr><tr><td><strong>schemaDigest</strong></td><td>SHA-256 over the RFC 8785 canonical Form Definition bytes.</td></tr><tr><td><strong>packageDigest</strong></td><td>SHA-256 over the RFC 8785 canonical package index; it is the publication locator (<code>sha256-&lt;hex&gt;</code>) of a package.</td></tr><tr><td><strong>Epoch</strong></td><td>The API-group boundary of the specification: <code>forms.takoform.com/v1alpha1</code> is the frozen Legacy epoch; <code>forms.takoform.com/v1alpha2</code> is retained as the provider-v2 epoch. Current design work uses namespaced Form Family groups instead of a new bare epoch.</td></tr><tr><td><strong>Form Family</strong></td><td>A namespaced Form group (<a href="/spec/form-families.html">Form Families</a>) such as <code>edge.forms.takoform.com/v1alpha1</code>, the Edge Platform Family: related Forms sharing exact Interface and Binding contracts. Family membership grants no maturity.</td></tr><tr><td><strong>Resource Role</strong></td><td>The closed v1alpha3 role enum — <code>identity</code>, <code>revision</code>, <code>deployment</code>, <code>attachment</code>, <code>policy</code> — deciding one Form&#39;s lifecycle mechanics: revisions are immutable, deployments move traffic, attachments activate inward events.</td></tr><tr><td><strong>Envelope</strong></td><td>The package API version used to carry a Form: <code>packages.forms.takoform.com/v1alpha4</code> for the current family lane; <code>packages.forms.takoform.com/v1alpha3</code> retained for provider-v2 packages.</td></tr><tr><td><strong>Space</strong></td><td>An opaque, case-sensitive scope identity (<code>SpaceID</code>) that scopes Resources, Interface reads, idempotency, and provider configuration.</td></tr><tr><td><strong>Host</strong></td><td>Any implementation of the Host API that advertises exact FormRefs, executes the portable lifecycle, and owns placement, credentials, and recovery.</td></tr><tr><td><strong>Host API</strong></td><td>The versioned HTTP contract (<a href="/spec/host-api/">host API</a>): discovery, exact Form availability, preview/apply, read/import/observe/refresh/delete, fencing, and stable errors. The current wire is <code>forms.takoform.com/v1alpha3</code>; <code>forms.takoform.com/v1alpha2</code> is the retained provider-v2 wire.</td></tr><tr><td><strong>Discovery</strong></td><td>The versioned well-known endpoint at which a host advertises its API, Forms, and features: <code>/.well-known/takoform/v1alpha3</code> for the current Host API; <code>/.well-known/takoform/v1alpha2</code> retained for provider v2.</td></tr><tr><td><strong>Lane</strong></td><td>A usage path through the single provider address: published <code>v1.0.3</code> for Legacy state and recovery; published <code>v2.0.0</code> for the nine retained provider-v2 Forms; <code>v2.1.0</code> (source candidate, not yet published) for the Edge Platform Family over the v1alpha3 Host API.</td></tr><tr><td><strong>Substrate</strong></td><td>The concrete backend or cloud an implementation runs on. Substrate operation is never portable Form state.</td></tr><tr><td><strong>Interface declaration</strong></td><td>A read-only <code>(name, version)</code> descriptor embedded in a Form Definition, projected by the host after the Resource is Ready (<a href="/spec/interface-declaration/">interface declaration</a>).</td></tr><tr><td><strong>Interface contract</strong></td><td>One exact named capability contract a Form&#39;s service exposes, such as <code>edge.kv@1.0.0</code> (<a href="/spec/interface-contract/">interface contracts</a>). A service with different semantics is a different contract, never a variant.</td></tr><tr><td><strong>Binding contract</strong></td><td>The typed contract behind one outward capability binding a revision holds, such as <code>module-worker.edge-kv@1.0.0</code> (<a href="/spec/binding-contract/">binding contracts</a>). Inward activation (routes, domains, cron, consumption) is an attachment, never a binding.</td></tr><tr><td><strong>artifact manifest</strong></td><td>The content-addressed manifest (<code>artifacts.takoform.com/v1alpha1</code>) that commits a bundle&#39;s modules by exact size and sha256 digest through the <a href="/spec/artifact-transport/">artifact transport</a> upload API.</td></tr><tr><td><strong>uid / generation / revision</strong></td><td>The v1alpha3 resource identity triple: <code>uid</code> is the host-issued immutable resource identity; <code>generation</code> increments only when the portable desired spec changes and fences updates; <code>revision</code> increments on any representation change and fences deletes.</td></tr><tr><td><strong>Proposal</strong></td><td>Mutable, unversioned design material for a Form that has not earned a public FormRef.</td></tr><tr><td><strong>Experimental</strong></td><td>A reproducible public Form on a <code>0.x</code> line whose semantics may still change under the documented compatibility policy.</td></tr><tr><td><strong>Stable</strong></td><td>An evidence-earned Form contract with independent implementations, interoperability, and operational experience.</td></tr><tr><td><strong>Legacy</strong></td><td>An immutable published identity retained for compatibility, recovery, and explicit migration but no longer the basis for new specification work.</td></tr><tr><td><strong>Admission</strong></td><td>The retired historical central-evidence process. There is no current central approval or admission.</td></tr><tr><td><strong>resource_version</strong></td><td>The retained v2 lane&#39;s canonical positive-decimal desired-state version; its quoted value is that lane&#39;s optimistic-concurrency fence (<code>ETag</code>). On the v1alpha3 lane the <code>ETag</code> is instead the quoted <code>revision</code>.</td></tr><tr><td><strong>Idempotency-Key</strong></td><td>A deterministic client-supplied key scoping mutation replay; a retry must reuse the same key and request bytes.</td></tr><tr><td><strong>Checkpoint</strong></td><td>A cumulative, hash-chained revocation checkpoint carrying every statement from sequence 1 through the current sequence.</td></tr><tr><td><strong>Drift</strong></td><td>A lifecycle outcome derived from validated observed evidence; it is not a separate host operation.</td></tr></tbody></table>',3)),s(t)])}const v=o(i,[["render",c]]);export{u as __pageData,v as default};
